let _mcache={};
function _mb64(s,T){const bin=atob(s),u=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)u[i]=bin.charCodeAt(i);return new T(u.buffer);}
const _mtex={};
function _modelTex(uri){if(!_mtex[uri]){const t=new THREE.TextureLoader().load(uri);t.wrapS=t.wrapT=THREE.RepeatWrapping;t.magFilter=THREE.NearestFilter;if('encoding' in t)t.encoding=THREE.sRGBEncoding;_mtex[uri]=t;}return _mtex[uri];}
function _modelParts(name){
 if(_mcache[name])return _mcache[name];
 const md=MODEL_DATA[name];
 const parts=md.parts.map(pt=>{
  const g=new THREE.BufferGeometry();
  g.setAttribute('position',new THREE.BufferAttribute(_mb64(pt.pos,Float32Array),3));
  g.setAttribute('normal',new THREE.BufferAttribute(_mb64(pt.nor,Float32Array),3));
  g.setAttribute('uv',new THREE.BufferAttribute(_mb64(pt.uv,Float32Array),2));
  g.setIndex(new THREE.BufferAttribute(_mb64(pt.idx,Uint16Array),1));
  const mat=new THREE.MeshLambertMaterial({color:new THREE.Color(pt.c[0],pt.c[1],pt.c[2]),map:pt.tex?_modelTex(pt.tex):null,side:THREE.DoubleSide});
  return {g,mat};
 });
 return _mcache[name]={top:md.top||0,parts};
}
/* Cria uma instância do modelo (geometria e materiais são compartilhados entre instâncias). */
function buildModel(name){
 const c=_modelParts(name),grp=new THREE.Group();
 for(const p of c.parts){const m=new THREE.Mesh(p.g,p.mat);m.castShadow=true;grp.add(m);}
 grp.userData.top=c.top;return grp;
}
